INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(1, 50, 'Laptop cao cấp từ Apple với chip M3 Pro mạnh mẽ, màn hình Liquid Retina XDR 14-inch siêu sắc nét, thời lượng pin lên đến 18 giờ. Lựa chọn hoàn hảo cho dân thiết kế đồ họa và lập trình viên chuyên nghiệp.', 'data:image/png;base64,', 39990000.00, 'Laptop Apple MacBook Pro 14 M3', 1);
INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(2, 30, 'Tuyệt tác thiết kế từ Dell với vỏ nhôm nguyên khối, viền màn hình siêu mỏng InfinityEdge OLED 3.5K. Trang bị vi xử lý Intel Core i7 thế hệ 13 và card đồ họa RTX 4050, đáp ứng mọi nhu cầu làm việc và giải trí.', 'data:image/png;base64,', 45500000.00, 'Laptop Dell XPS 15 9530', 1);
INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(3, 100, 'Siêu phẩm smartphone với khung Titanium siêu nhẹ và bền bỉ. Trang bị chip A17 Pro mạnh mẽ nhất thế giới mobile, hệ thống camera xuất sắc với khả năng zoom quang học 5x. Trải nghiệm giải trí đỉnh cao.', 'data:image/png;base64,', 34990000.00, 'Điện thoại iPhone 15 Pro Max 256GB', 2);
INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(4, 85, 'Điện thoại AI đầu tiên từ Samsung với khung viền Titan. Đi kèm bút S Pen đa năng, màn hình phẳng 6.8 inch Dynamic AMOLED 2X, camera 200MP chụp đêm siêu việt và các tính năng Galaxy AI đột phá.', 'data:image/png;base64,', 33990000.00, 'Điện thoại Samsung Galaxy S24 Ultra', 2);
INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(5, 120, 'Tai nghe chụp tai chống ồn chủ động (ANC) dẫn đầu thị trường. Thiết kế hoàn toàn mới, nhẹ và thoải mái hơn. Công nghệ AI tối ưu hóa khả năng chống ồn và đàm thoại, thời lượng pin 30 giờ liên tục.', 'data:image/jpeg;base64,', 7990000.00, 'Tai nghe Sony WH-1000XM5', 3);
INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(6, 60, 'Smartwatch thế hệ mới nhất với chip S9 SiP nhanh hơn, độ sáng màn hình gấp đôi thế hệ trước. Tích hợp tính năng thao tác chạm hai lần (Double Tap) kỳ diệu để nhận cuộc gọi mà không cần chạm màn hình.', 'data:image/webp;base64,', 10490000.00, 'Đồng hồ Apple Watch Series 9', 4);
INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(7, 40, 'Bàn phím cơ custom không dây với khung nhôm CNC nguyên khối cực đầm tay. Hỗ trợ QMK/VIA để tùy chỉnh phím tự do, kết nối Bluetooth đa thiết bị, switch cơ học gõ siêu êm ái dành cho dân văn phòng.', 'data:image/jpeg;base64,', 4500000.00, 'Bàn phím cơ Keychron Q1 Pro', 5);
INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(8, 200, 'Chuột không dây công thái học tốt nhất thế giới. Cảm biến 8000 DPI siêu nhạy hoạt động trên mọi bề mặt kể cả kính. Nút bấm Quiet Clicks giảm 90% tiếng ồn, con lăn MagSpeed cuộn 1000 dòng/giây.', 'data:image/webp;base64,', 2590000.00, 'Chuột không dây Logitech MX Master 3S', 5);
INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(9, 25, 'Màn hình chuyên đồ họa với độ phân giải 4K UHD, tấm nền IPS cho màu sắc trung thực 99% sRGB. Hỗ trợ cổng USB-C sạc ngược 90W vô cùng tiện lợi khi kết nối với laptop, thiết kế viền mỏng hiện đại.', 'data:image/jpeg;base64,', 12500000.00, 'Màn hình LG UltraFine 4K 27 inch', 6);
INSERT INTO `products` (`id`, `availability`, `discription`, `image`, `price`, `product_name`, `category_id`) VALUES
(10, 75, 'Máy tính bảng mạnh nhất hiện nay với chip Apple M2. Màn hình Liquid Retina mượt mà 120Hz ProMotion. Hỗ trợ Apple Pencil 2 với tính năng lướt (Hover) siêu nhạy, thay thế hoàn hảo cho máy tính xách tay cơ bản.', 'data:image/png;base64,', 21990000.00, 'Máy tính bảng iPad Pro 11 inch M2', 1);

